package com.stankhouse.scooterspeedometer;

import android.Manifest;import android.app.Activity;import android.app.AlertDialog;import android.content.ClipData;import android.content.ClipboardManager;import android.content.pm.PackageManager;import android.graphics.Color;import android.location.Location;import android.location.LocationListener;import android.location.LocationManager;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.speech.tts.TextToSpeech;import android.view.Gravity;import android.webkit.WebSettings;import android.webkit.WebView;import android.widget.Button;import android.widget.CheckBox;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import org.json.JSONArray;import org.json.JSONObject;import java.util.Locale;

/** RiderLink+ live convoy rooms with rider tracking, gap monitoring and voice-safe alerts. */
public class GroupRideActivity extends Activity implements LocationListener{
 private RiderLinkClient client;private LocationManager locations;private Location fix;private LinearLayout content,members;private TextView status,alertFeed;private WebView map;private long activeRide,lastAlertId,lastGapWarning;private String activeName="",activeCode="",activeRole="rider";private boolean mapReady;private TextToSpeech speech;private boolean speechReady;private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable refresh=new Runnable(){public void run(){if(activeRide>0)refreshConvoy();else loadLobby();handler.postDelayed(this,5000L);}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);Fullscreen.apply(this);client=new RiderLinkClient(this);locations=(LocationManager)getSystemService(LOCATION_SERVICE);speech=new TextToSpeech(this,s->{speechReady=s==TextToSpeech.SUCCESS;if(speechReady){speech.setLanguage(Locale.US);VoiceSettings.apply(this,speech);}});buildShell();startGps();client.membership((ok,m,d)->loadLobby());handler.post(refresh);}
 private void buildShell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackground(UiKit.screenBackground(this));LinearLayout head=UiKit.header(this,"⌖","RiderLink+ Convoy","LIVE GROUP RIDING");Button close=UiKit.iconButton(this,"×","Close",UiKit.SURFACE_HIGH);close.setOnClickListener(v->finish());head.addView(close,new LinearLayout.LayoutParams(dp(86),dp(46)));root.addView(head,new LinearLayout.LayoutParams(-1,dp(74)));status=UiKit.text(this,"Temporary sharing stays off until you enter a convoy",12,UiKit.MUTED,false);status.setGravity(Gravity.CENTER);root.addView(status,new LinearLayout.LayoutParams(-1,dp(36)));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void loadLobby(){client.myActiveGroupRides((ok,m,body)->{if(activeRide>0)return;content.removeAllViews();LinearLayout actions=new LinearLayout(this);actions.setPadding(dp(10),dp(4),dp(10),dp(8));Button create=button("+ CREATE",UiKit.SURFACE_ACTIVE),join=button("→ JOIN CODE",UiKit.SURFACE_HIGH);actions.addView(create,new LinearLayout.LayoutParams(0,dp(52),1));actions.addView(join,new LinearLayout.LayoutParams(0,dp(52),1));content.addView(actions);create.setOnClickListener(v->{if(client.plusActive())createDialog();else new AlertDialog.Builder(this).setTitle("RiderLink+ required").setMessage("Creating and leading a Convoy is a Plus feature. Joining an existing Convoy and receiving safety alerts remains free.").setPositiveButton("OK",null).show();});join.setOnClickListener(v->joinDialog());ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(12),0,dp(12),dp(18));scroll.addView(list);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));list.addView(UiKit.section(this,"⌖","My active convoys"));if(!ok){list.addView(message(m+" • Run the v8.7 Convoy SQL migration"));return;}try{JSONArray rides=new JSONArray(body);if(rides.length()==0)list.addView(message("No active convoy. Enter a code to join, or create one with RiderLink+."));for(int i=0;i<rides.length();i++){JSONObject ride=rides.getJSONObject(i);LinearLayout card=new LinearLayout(this);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(14),dp(8),dp(8),dp(8));UiKit.card(card);TextView info=UiKit.text(this,ride.optString("name","Convoy")+"\n"+ride.optString("destination","Open destination")+"\n"+ride.optInt("member_count",1)+" riders • "+ride.optString("role","rider"),14,UiKit.TEXT,true);card.addView(info,new LinearLayout.LayoutParams(0,dp(84),1));Button enter=button("ENTER",UiKit.SURFACE_ACTIVE);enter.setOnClickListener(v->openConvoy(ride));card.addView(enter,new LinearLayout.LayoutParams(dp(84),dp(48)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(100));lp.setMargins(0,0,0,dp(8));list.addView(card,lp);}}catch(Exception e){list.addView(message(e.getMessage()));}});}
 private void openConvoy(JSONObject ride){activeRide=ride.optLong("id");activeName=ride.optString("name","Convoy");activeCode=ride.optString("invite_code","");activeRole=ride.optString("role","rider");content.removeAllViews();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(12),dp(4),dp(12),dp(6));TextView title=UiKit.text(this,activeName+"\n"+ride.optString("destination","Open destination")+(ride.optBoolean("avoid_highways",true)?" • Scooter-safe":""),15,UiKit.TEXT,true);top.addView(title,new LinearLayout.LayoutParams(0,dp(58),1));Button code=button("CODE "+activeCode,UiKit.SURFACE_HIGH);code.setOnClickListener(v->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Convoy code",activeCode));toast("Invite code copied");});top.addView(code,new LinearLayout.LayoutParams(dp(132),dp(48)));content.addView(top);map=new WebView(this);map.setLayerType(android.view.View.LAYER_TYPE_HARDWARE,null);WebSettings s=map.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);map.setWebViewClient(new android.webkit.WebViewClient(){@Override public void onPageFinished(WebView v,String u){mapReady=true;refreshConvoy();}});map.loadUrl("file:///android_asset/convoy_map.html");content.addView(map,new LinearLayout.LayoutParams(-1,0,1));addQuickAlerts();ScrollView lower=new ScrollView(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(10),dp(4),dp(10),dp(10));members=new LinearLayout(this);members.setOrientation(LinearLayout.VERTICAL);alertFeed=UiKit.text(this,"No recent convoy alerts",12,UiKit.MUTED,false);panel.addView(UiKit.section(this,"●","Riders"));panel.addView(members);panel.addView(UiKit.section(this,"!","Recent alerts"));panel.addView(alertFeed);Button leave=button("leader".equals(activeRole)?"END CONVOY":"LEAVE CONVOY",UiKit.RED);leave.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(leave.getText()).setMessage("Live location sharing for this convoy will stop.").setPositiveButton("CONFIRM",(d,w)->client.leaveConvoy(activeRide,(ok,m,b)->{toast(ok?"Convoy closed":m);if(ok)exitConvoy();})).setNegativeButton("Cancel",null).show());panel.addView(leave,new LinearLayout.LayoutParams(-1,dp(52)));lower.addView(panel);content.addView(lower,new LinearLayout.LayoutParams(-1,dp(260)));status.setText("LIVE CONVOY • location shared only with room members");refreshConvoy();}
 private void addQuickAlerts(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(4),dp(8),dp(4));String[][] rows={{"⦿ REGROUP","⛽ FUEL","🔧 MECHANICAL"},{"⚠ HAZARD","★ POLICE","↘ PULL OVER"}};String[][] types={{"regroup","fuel","mechanical"},{"hazard","police","pull_over"}};for(int r=0;r<2;r++){LinearLayout row=new LinearLayout(this);for(int i=0;i<3;i++){Button b=button(rows[r][i],r==0?UiKit.SURFACE_HIGH:Color.rgb(91,42,20));b.setTextSize(10);String type=types[r][i];b.setOnClickListener(v->sendAlert(type));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(46),1);lp.setMargins(dp(2),0,dp(2),dp(4));row.addView(b,lp);}box.addView(row);}content.addView(box);}
 private void refreshConvoy(){if(activeRide<=0)return;if(fix!=null)client.updateGroupRideLocation(activeRide,fix.getLatitude(),fix.getLongitude(),fix.getSpeed(),(o,m,b)->{});client.convoySnapshot(activeRide,(ok,m,body)->{if(!ok){status.setText(m);return;}if(mapReady){String safe=body.replace("\\","\\\\").replace("'","\\'").replace("\n","");map.evaluateJavascript("setConvoy('"+safe+"')",null);}renderMembers(body);});client.convoyAlerts(activeRide,(ok,m,body)->{if(ok)renderAlerts(body);});}
 private void renderMembers(String body){if(members==null)return;members.removeAllViews();try{JSONArray list=new JSONArray(body);double worst=0;String behind="";for(int i=0;i<list.length();i++){JSONObject r=list.getJSONObject(i);int age=r.optInt("age_seconds",999);double gap=r.optDouble("distance_from_leader_m",0);if(!"leader".equals(r.optString("role"))&&age<45&&gap>worst){worst=gap;behind=r.optString("username","Rider");}String state=age>45?"SIGNAL LOST":Math.round(r.optDouble("speed_mps")*2.2369)+" mph"+(gap>800?" • FALLING BEHIND":"");TextView line=UiKit.text(this,("leader".equals(r.optString("role"))?"★ ":"🛵 ")+r.optString("username","Rider")+" • "+state,12,gap>800?Color.rgb(255,179,0):UiKit.TEXT,true);members.addView(line,new LinearLayout.LayoutParams(-1,dp(32)));}long now=System.currentTimeMillis();if("leader".equals(activeRole)&&worst>800&&now-lastGapWarning>120000){lastGapWarning=now;speak(behind+" is falling behind");}}catch(Exception e){members.addView(message("Waiting for rider positions…"));}}
 private void renderAlerts(String body){try{JSONArray list=new JSONArray(body);StringBuilder out=new StringBuilder();for(int i=0;i<Math.min(5,list.length());i++){JSONObject a=list.getJSONObject(i);if(i==0&&a.optLong("id")>lastAlertId){if(lastAlertId>0)speak(a.optString("username","Rider")+": "+a.optString("message"));lastAlertId=a.optLong("id");}out.append(a.optString("username","Rider")).append(" • ").append(a.optString("message")).append('\n');}alertFeed.setText(out.length()==0?"No recent convoy alerts":out.toString().trim());}catch(Exception ignored){}}
 private void sendAlert(String type){if(activeRide<=0)return;client.sendConvoyAlert(activeRide,type,fix==null?null:fix.getLatitude(),fix==null?null:fix.getLongitude(),(ok,m,b)->{toast(ok?"Convoy alert sent":m);if(ok)refreshConvoy();});}
 private void exitConvoy(){if(activeRide>0)client.stopGroupRideLocation(activeRide,(o,m,b)->{});activeRide=0;mapReady=false;if(map!=null){map.destroy();map=null;}status.setText("Convoy location sharing stopped");loadLobby();}
 private void createDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),0,dp(16),0);EditText name=field("Convoy name"),dest=field("Destination / meeting point");CheckBox avoid=new CheckBox(this);avoid.setText("Avoid highways • scooter-safe route");avoid.setTextColor(Color.WHITE);avoid.setChecked(true);box.addView(name);box.addView(dest);box.addView(avoid);new AlertDialog.Builder(this).setTitle("Create RiderLink+ Convoy").setView(box).setPositiveButton("CREATE",(d,w)->client.createConvoy(name.getText().toString().trim(),dest.getText().toString().trim(),avoid.isChecked(),(ok,m,b)->{toast(ok?"Convoy created":m);loadLobby();})).setNegativeButton("Cancel",null).show();}
 private void joinDialog(){EditText code=field("8-character invite code");code.setAllCaps(true);new AlertDialog.Builder(this).setTitle("Join Convoy").setView(code).setPositiveButton("JOIN",(d,w)->client.joinGroupRide(code.getText().toString().trim(),(ok,m,b)->{toast(ok?"Joined Convoy":m);loadLobby();})).setNegativeButton("Cancel",null).show();}
 private Button button(String text,int color){Button b=new Button(this);b.setText(text);UiKit.button(b,color);return b;}private EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);UiKit.field(e);return e;}private TextView message(String text){TextView t=UiKit.text(this,text,14,UiKit.MUTED,false);t.setGravity(Gravity.CENTER);t.setPadding(dp(12),dp(18),dp(12),dp(18));return t;}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}private int dp(int v){return UiKit.dp(this,v);}private void speak(String text){if(speechReady)speech.speak(text,TextToSpeech.QUEUE_ADD,null,"convoy_"+System.currentTimeMillis());}
 private void startGps(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},81);return;}try{locations.requestLocationUpdates(LocationManager.GPS_PROVIDER,1500,2,this);}catch(Exception ignored){}}@Override public void onLocationChanged(Location l){fix=l;}@Override public void onProviderEnabled(String p){}@Override public void onProviderDisabled(String p){}@Override public void onStatusChanged(String p,int s,Bundle b){}@Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==81&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startGps();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);try{locations.removeUpdates(this);}catch(Exception ignored){}if(activeRide>0)client.stopGroupRideLocation(activeRide,(o,m,b)->{});if(client!=null)client.shutdown();if(speech!=null){speech.stop();speech.shutdown();}if(map!=null)map.destroy();super.onDestroy();}@Override public void onWindowFocusChanged(boolean f){super.onWindowFocusChanged(f);if(f)Fullscreen.apply(this);}
}
